import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        Map<String, String[]> needs = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            needs.put(parts[0], parts[1].equals("-") ? new String[0] : parts[1].split(","));
        }
        int k = Integer.parseInt(sc.nextLine().trim());
        String[] order = sc.nextLine().trim().split("\\s+");

        Set<String> executed = new LinkedHashSet<>();
        List<String> problems = new ArrayList<>();
        int ok = 0;
        for (int i = 0; i < k; i++) {
            String step = order[i];
            List<String> missing = new ArrayList<>();
            for (String need : needs.getOrDefault(step, new String[0])) {
                if (!executed.contains(need)) {
                    missing.add(need);
                }
            }
            if (missing.isEmpty()) {
                ok++;
            } else {
                problems.add("NG " + step + " " + String.join(",", missing));
            }
            executed.add(step);
        }

        List<String> notRun = new ArrayList<>();
        for (String step : needs.keySet()) {
            if (!executed.contains(step)) {
                notRun.add("MISSING " + step);
            }
        }

        System.out.println(problems.isEmpty() && notRun.isEmpty() ? "OK" : "NG");
        problems.forEach(System.out::println);
        notRun.forEach(System.out::println);
        System.out.println("成立 " + ok + "/" + k);
    }
}

