import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] head = sc.nextLine().trim().split("\\s+");
        double threshold = Double.parseDouble(head[0]);
        int needed = Integer.parseInt(head[1]);
        int n = Integer.parseInt(sc.nextLine().trim());
        String[] parts = sc.nextLine().trim().split("\\s+");

        double max = 0;
        int over = 0;
        int streak = 0;
        int longest = 0;
        for (int i = 0; i < n; i++) {
            double rate = Double.parseDouble(parts[i]);
            max = Math.max(max, rate);
            if (rate > threshold) {
                over++;
                streak++;
                longest = Math.max(longest, streak);
            } else {
                streak = 0;
            }
        }

        System.out.printf("最大 %.1f%n", max);
        System.out.println("超過 " + over);
        System.out.println("最長連続 " + longest);
        System.out.println("判定 " + (longest >= needed ? "切り戻し" : "継続"));
    }
}

