        double allowed = Double.parseDouble(sc.nextLine().trim());
        int n = Integer.parseInt(sc.nextLine().trim());
        boolean stopped = false;
        String reached = "なし";
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            if (stopped) {
                System.out.println(parts[0] + " 未実施");
                continue;
            }
            double rate = Double.parseDouble(parts[1]);
            if (rate <= allowed) {
                reached = parts[0];
                System.out.println(parts[0] + " 進む");
            } else {
                stopped = true;
                System.out.println(parts[0] + " 止める");
            }
        }
        System.out.println("到達 " + reached);
    }
}

