import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] head = sc.nextLine().trim().split("\\s+");
        int n = Integer.parseInt(head[0]);
        int tolerance = Integer.parseInt(head[1]);
        int fromTotal = 0;
        int toTotal = 0;
        boolean allMatch = true;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            int from = Integer.parseInt(parts[1]);
            int to = Integer.parseInt(parts[2]);
            int diff = to - from;
            boolean match = Math.abs(diff) <= tolerance;
            if (!match) {
                allMatch = false;
            }
            fromTotal += from;
            toTotal += to;
            System.out.println(parts[0] + " 差 " + diff + " " + (match ? "一致" : "不一致"));
        }
        System.out.println("合計 移行元 " + fromTotal + " 移行先 " + toTotal);
        System.out.println("判定 " + (allMatch ? "移行成功" : "要調査"));
    }
}

