import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine().trim());
        String[] stages = {"承認", "実施", "記録"};
        List<String> problems = new ArrayList<>();
        int clean = 0;
        for (int i = 0; i < n; i++) {
            String[] parts = sc.nextLine().trim().split("\\s+");
            List<String> found = new ArrayList<>();
            for (int stage = 0; stage < stages.length; stage++) {
                String previous = parts[stage + 1];
                String current = parts[stage + 2];
                if (current.equals("-")) {
                    continue;
                }
                if (previous.equals("-") || current.compareTo(previous) < 0) {
                    found.add(stages[stage]);
                }
            }
            if (found.isEmpty()) {
                clean++;
            } else {
                for (String stage : found) {
                    problems.add("NG " + parts[0] + " " + stage);
                }
            }
        }
        System.out.println(problems.isEmpty() ? "OK" : "NG");
        problems.forEach(System.out::println);
        System.out.println("正常 " + clean + "/" + n);
    }
}
